try:
    print('>>> f = filter')
    print('>>> x = 2.3456')
    print('>>> y = frozenset()')
    print('>>> f(x, y)')
    f = filter
    x = 2.3456
    y = frozenset()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
